// A stand-in for playwright-core, just enough for scripts/remote_login.js to run without a browser.
// The test drives the "page" through a JSON state file (FAKE_PW_STATE: url, text, canvas, refresh) and reads what the script
// did from a JSON-lines log (FAKE_PW_LOG). Not a mock of Playwright's behavior: only its surface as remote_login.js uses it.
const fs = require('fs');
// The test rewrites the state file while the session runs: retry a read that caught it half-written instead of dying on it.
const state = () => {
  for (let i = 0; ; i++) {
    try { return JSON.parse(fs.readFileSync(process.env.FAKE_PW_STATE, 'utf8')); } catch (e) { if (i >= 20) throw e; Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 5); }
  }
};
const save = (s) => fs.writeFileSync(process.env.FAKE_PW_STATE, JSON.stringify(s));
const log = (o) => fs.appendFileSync(process.env.FAKE_PW_LOG, JSON.stringify(o) + '\n');
const png = () => Buffer.from(process.env.FAKE_PW_PNG_B64, 'base64');

const page = {
  url: () => state().url,
  goto: async (u) => {
    log({ op: 'goto', url: u });
    if (u.includes('SLOW')) await new Promise((r) => setTimeout(r, 400));
    if (u.includes('FAILME')) throw new Error('net::ERR_FAILED at ' + u);
    save({ ...state(), url: u });
  },
  evaluate: async (fn) => { if (state().evalFails) throw new Error('Execution context was destroyed'); return String(fn).includes('innerHTML') ? '<html></html>' : state().text; },
  screenshot: async ({ path }) => fs.writeFileSync(path, png()),
  $: async (sel) => {
    const s = state();
    if (sel === 'canvas') return s.canvas ? { screenshot: async ({ path }) => { log({ op: 'qr_shot' }); fs.writeFileSync(path, png()); } } : null;
    if (sel === 'text=刷新二维码') return s.refresh ? { click: async () => { log({ op: 'refresh' }); save({ ...state(), refresh: false }); } } : null;
    return null;
  },
  fill: async (sel) => { log({ op: 'fill', sel }); },
  click: async (sel) => { log({ op: 'click', sel }); if (sel.includes('MISSING')) throw new Error('no element matches ' + sel); },
  // state.flip = {waits, url, text}: a client-side redirect that lands after that many waits (the page looked fine until then)
  waitForTimeout: (ms) => {
    log({ op: 'wait', ms });
    const s = state();
    if (s.flip && s.flip.waits > 0 && --s.flip.waits === 0) { s.url = s.flip.url; s.text = s.flip.text; save(s); }
    else if (s.flip && s.flip.waits >= 0) save(s);
    return new Promise((r) => setTimeout(r, Math.min(ms, 15)));
  },
};

module.exports = {
  chromium: {
    launchPersistentContext: async (dir, opts) => {
      log({ op: 'launch', dir, args: opts.args || [], executablePath: opts.executablePath, viewport: opts.viewport });
      return { pages: () => [page], newPage: async () => page, close: async () => log({ op: 'close' }) };
    },
  },
};
